public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    try {
        if (n <= 0) {
            return "cannot be travelled";
        }
        int startKey = knot(start, n);
        int endKey = knot(end, n);
        if (startKey == endKey) {
            return "can be travelled";
        }

        // Build adjacency list
        Map<Integer, List<Integer>> adjacency = new HashMap<>();
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int key = knot(new int[]{i, j}, n);
                adjacency.put(key, new ArrayList<>());
            }
        }

        for (int[] path : paths) {
            if (path.length < 4) continue;
            int a = path[0];
            int b = path[1];
            int c = path[2];
            int d = path[3];
            if (a >= 0 && a < n && b >= 0 && b < n && c >= 0 && c < n && d >= 0 && d < n) {
                int key1 = knot(new int[]{a, b}, n);
                int key2 = knot(new int[]{c, d}, n);
                adjacency.get(key1).add(key2);
                adjacency.get(key2).add(key1);
            }
        }

        // BFS
        Set<Integer> visited = new HashSet<>();
        Queue<Integer> queue = new LinkedList<>();
        queue.offer(startKey);
        visited.add(startKey);

        while (!queue.isEmpty()) {
            int current = queue.poll();
            if (current == endKey) {
                return "can be travelled";
            }
            for (int neighbor : adjacency.getOrDefault(current, Collections.emptyList())) {
                if (!visited.contains(neighbor)) {
                    visited.add(neighbor);
                    queue.offer(neighbor);
                }
            }
        }

        return "cannot be travelled";
    } catch (Exception e) {
        return "cannot be travelled";
    }
}

public static String appx(String word1, String word2) {
    if (word1 == null || word2 == null) {
        throw new IllegalArgumentException("Input strings cannot be null");
    }

    int commonCount = 0;
    char[] chars1 = word1.toUpperCase().toCharArray();
    char[] chars2 = word2.toUpperCase().toCharArray();
    boolean[] matched2 = new boolean[chars2.length];

    for (char c1 : chars1) {
        for (int j = 0; j < chars2.length; j++) {
            if (!matched2[j] && c1 == chars2[j]) {
                commonCount++;
                matched2[j] = true;
                break;
            }
        }
    }

    int totalLength = word1.length() + word2.length();
    String result;

    if (commonCount == 0) {
        result = "0";
    } else if (commonCount == totalLength) {
        result = "1";
    } else {
        int gcd = gcd(commonCount, totalLength);
        int numerator = commonCount / gcd;
        int denominator = totalLength / gcd;
        if (denominator == 1) {
            result = String.valueOf(numerator);
        } else {
            result = numerator + "/" + denominator;
        }
    }

    return "appx(" + word1 + ", " + word2 + ") = " + result;
}

