}

public boolean canArrange(int[] arr, int k) {
    if (arr == null || arr.length == 0 || arr.length % 2 != 0 || k <= 0) {
        return false;
    }
    int[] counts = new int[k];
    for (int num : arr) {
        int mod = ((num % k) + k) % k;
        counts[mod]++;
    }
    if (counts[0] % 2 != 0) {
        return false;
    }
    for (int i = 1; i <= k / 2; i++) {
        if (i == k - i) {
            if (counts[i] % 2 != 0) {
                return false;
            }
        } else {
            if (counts[i] != counts[k - i]) {
                return false;
            }
        }
    }
    return true;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            adj.add(new ArrayList<>());
        }
        for (int[] edge : edges) {
            int u = edge[0];
            int v = edge[1];
            adj.get(u).add(v);
            adj.get(v).add(u);
        }

        // DFS: returns the time needed to explore the subtree rooted at node
        // and return to its parent. If no apple in the subtree, returns 0.
        // We use a visited array to avoid going back to parent.
        boolean[] visited = new boolean[n];
        int[] result = new int[1];

        private int dfs(int node, int parent, List<List<Integer>> adj, boolean[] hasApple, boolean[] visited) {
            visited[node] = true;
            int total = 0;
            boolean subtreeHasApple = hasApple[node];

            for (int neighbor : adj.get(node)) {
                if (neighbor == parent) {
                    continue;
                }
                if (visited[neighbor]) {
                    continue;
                }

                int childTime = dfs(neighbor, node, adj, hasApple, visited);
                if (childTime > 0) {
                    total += childTime + 2;
                    subtreeHasApple = true;
                }
            }

            if (!subtreeHasApple && node != 0) {
                return 0;
            }
            return total;
        }

        return dfs(0, -1, adj, hasApple, visited);
    }

public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return s;
    }

    int[] count = new int[26];
    for (char c : s.toCharArray()) {
        count[c - 'a']++;
    }

    StringBuilder result = new StringBuilder();
    int remaining = s.length();

    while (remaining > 0) {
        // Ascending: smallest to larger
        for (int i = 0; i < 26 && remaining > 0; i++) {
            if (count[i] > 0) {
                result.append((char) ('a' + i));
                count[i]--;
                remaining--;
            }
        }

        // Descending: largest to smaller
        for (int i = 25; i >= 0 && remaining > 0; i--) {
            if (count[i] > 0) {
                result.append((char) ('a' + i));
                count[i]--;
                remaining--;
            }
        }
    }

    return result.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n < 2) {
        return false;
    }
    // If one element is both smaller than the rest and larger than the rest, can't split.
    // More practically: if k=1 is possible, then we check if any single element equals the average.
    // The average of the whole array: totalSum / n
    // If a subset of size k has the same average, then subset sum = k * totalSum / n
    // This must be an integer. So k * totalSum must be divisible by n.

    int totalSum = 0;
    int minVal = Integer.MAX_VALUE;
    int maxVal = Integer.MIN_VALUE;
    for (int v : nums) {
        totalSum += v;
        if (v < minVal) minVal = v;
        if (v > maxVal) maxVal = v;
    }

    // Special check: if minVal + maxVal == 2 * (totalSum / n) but totalSum/n not integer, 
    // Actually a simpler necessary condition: if k*totalSum % n != 0, then no subset of size k works.

    // We iterate k from 1 to n/2 (since we can swap the two parts, only need to check up to n/2)
    // Actually, we need to check k from 1 to n-1, but k and n-k are symmetric. Check k from 1 to n/2.
    // But we must ensure that (totalSum * k) is divisible by n for subset sum to be integer.

    for (int k = 1; k <= n / 2; k++) {
        if (totalSum * k % n != 0) {
            continue;
        }
        int targetSum = totalSum * k / n;
        // Check if any subset of size k sums to targetSum.
        // Use set of possible sums for subsets of size k.
        // For k=1: check if any element equals targetSum.
        if (k == 1) {
            boolean found = false;
            for (int v : nums) {
                if (v == targetSum) {
                    found = true;
                    break;
                }
            }
            if (found) {
                return true;
            }
            continue;
        }

        // DP: possible sums for subsets of size k
        // Initialize: dp[0] = 0 (empty subset, size 0, sum 0). But we need subsets of exactly size k.
        // Let dp[j] be a set of possible sums for subsets of size j.
        // j ranges from 0 to k.

        // To avoid using too much memory and time, we can use a boolean array if the range of sums is bounded,
        // but sums can be large. Alternatively, use a Set for each j up to k.

        // Use a list of sets: sets[j] contains all possible sums of subsets of size j.
        Set<Integer> sets[] = new Set[k + 1];
        for (int i = 0; i <= k; i++) {
            sets[i] = new HashSet<>();
        }
        sets[0].add(0);

        for (int num : nums) {
            // Iterate j from k down to 1 to avoid using same element multiple times
            for (int j = k; j >= 1; j--) {
                Set<Integer> currentSet = new HashSet<>();
                for (int s : sets[j - 1]) {
                    int newSum = s + num;
                    currentSet.add(newSum);
                }
                sets[j].addAll(currentSet);
            }
        }

        if (sets[k].contains(targetSum)) {
            return true;
        }
    }

    return false;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        return 0;
    }
    if (cost.length == 1) {
        return cost[0];
    }

    int n = cost.length;
    int[] dp = new int[n + 1];
    dp[0] = 0;
    dp[1] = 0;

    for (int i = 2; i <= n; i++) {
        dp[i] = Math.min(dp[i - 1] + cost[i - 1], dp[i - 2] + cost[i - 2]);
    }

    return dp[n];
}

public int uniqueMorseRepresentations(String[] words) {
    if (words == null || words.length == 0) {
        return 0;
    }

    String[] morse = {
        ".-", "-...", "-.-.", "-..", ".", "..-.", "--.", "....",
        "..", ".---", "-.-", "--.", "-.", "---", ".--.", "- -",
        "--.-", ".-.", "...", "-", ".---", "...", "..",
        ".--", "-..-", "-.--"
    };

    java.util.Set<String> transformations = new java.util.HashSet<>();

    for (String word : words) {
        StringBuilder sb = new StringBuilder();
        for (char c : word.toCharArray()) {
            int index = c - 'a';
            if (index >= 0 && index < 26) {
                sb.append(morse[index]);
            }
        }
        transformations.add(sb.toString());
    }

    return transformations.size();
}

public boolean hasAllCodes(String s, int k) {
    if (s == null || s.isEmpty()) {
        return k == 0;
    }
    if (k == 0) {
        return true;
    }
    if (s.length() < k) {
        return false;
    }

    int total = 1 << k;
    boolean[] seen = new boolean[total];
    int count = 0;

    // First window
    int mask = 0;
    for (int i = 0; i < k; i++) {
        char c = s.charAt(i);
        mask = (mask << 1) | (c - '0');
    }
    if (!seen[mask]) {
        seen[mask] = true;
        count++;
    }

    // Slide the window
    for (int i = k; i < s.length(); i++) {
        char c = s.charAt(i);
        mask = ((mask << 1) & (total - 1)) | (c - '0');
        if (!seen[mask]) {
            seen[mask] = true;
            count++;
        }
    }

    return count == total;
}

