    int minSum = Integer.MAX_VALUE;
    int currentMax = 0;
    int currentMin = 0;

    for (int num : nums) {
        currentMax = Math.max(num, currentMax + num);
        currentMin = Math.min(num, currentMin + num);

        maxSum = Math.max(maxSum, currentMax);
        minSum = Math.min(minSum, currentMin);
    }

    return Math.max(Math.abs(maxSum), Math.abs(minSum));
}

public int findMinFibonacciNumbers(int k) {
    if (k <= 0) {
        return 0;
    }

    // Generate Fibonacci numbers up to k
    List<Integer> fibs = new ArrayList<>();
    fibs.add(1);
    fibs.add(2); // We can think of F1=1, F2=1, but for greedy selection we use distinct sequence 1, 2, 3, 5, 8...
    // Actually, the standard Fibonacci used for this problem is 1, 1, 2, 3, 5, 8, 13...
    // But since greedy works with the sequence, let's generate properly.

    // Let's regenerate properly: F1=1, F2=2 (to avoid duplicate 1s which don't help in minimum count)
    // Actually, using 1, 2, 3, 5, 8... is standard for this greedy approach.

    // Clear and regenerate
    fibs.clear();
    fibs.add(1);
    fibs.add(2);

    int a = 1, b = 2;
    while (true) {
        int next = a + b;
        if (next > k) {
            break;
        }
        fibs.add(next);
        a = b;
        b = next;
    }

    // Greedy: pick largest Fibonacci number <= remaining k
    int count = 0;
    int remaining = k;
    for (int i = fibs.size() - 1; i >= 0; i--) {
        if (fibs.get(i) <= remaining) {
            count++;
            remaining -= fibs.get(i);
            if (remaining == 0) {
                break;
            }
        }
    }

    return count;
}

public int kthFactor(int n, int k) {
    if (n <= 0 || k <= 0) {
        return -1;
    }

    int count = 0;
    for (int i = 1; i * i <= n; i++) {
        if (n % i == 0) {
            count++;
            if (count == k) {
                return i;
            }
        }
    }

    // Collect the larger factors in descending order, then process them in ascending order
    java.util.List<Integer> upperFactors = new java.util.ArrayList<>();
    for (int i = (int) Math.sqrt(n); i >= 1; i--) {
        if (n % i == 0) {
            int factor = n / i;
            if (factor > i) {
                upperFactors.add(factor);
            }
        }
    }

    // upperFactors is currently in descending order, so reverse it to get ascending
    for (int i = upperFactors.size() - 1; i >= 0; i--) {
        count++;
        if (count == k) {
            return upperFactors.get(i);
        }
    }

    return -1;
}

public String makeGood(String s) {
    if (s == null || s.length() <= 1) {
        return s;
    }
    StringBuilder stack = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (stack.length() > 0) {
            char prev = stack.charAt(stack.length() - 1);
            if (Math.abs(prev - c) == 32 && Character.isLetter(prev) && Character.isLetter(c)) {
                stack.deleteCharAt(stack.length() - 1);
                continue;
            }
        }
        stack.append(c);
    }
    return stack.toString();
}

