public static int singleNumber(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }

    int ones = 0;
    int twos = 0;

    for (int num : nums) {
        // ones: bits that have appeared 1 mod 3 times
        // twos: bits that have appeared 2 mod 3 times
        twos |= ones & num;
        ones ^= num;

        int threes = ones & twos;
        ones &= ~threes;
        twos &= ~threes;
    }

    return ones;
}

public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low > high) {
        return result;
    }

    // Handle the case where low is 0
    if (low == 0) {
        result.add(0);
    }

    // BFS/DFS approach starting from each single digit 1-9
    Queue<Integer> queue = new ArrayDeque<>();
    for (int i = 1; i <= 9; i++) {
        queue.offer(i);
    }

    while (!queue.isEmpty()) {
        int num = queue.poll();
        if (num > high) {
            continue;
        }
        if (num >= low) {
            result.add(num);
        }

        int lastDigit = num % 10;
        int multiplier = num * 10;

        // Try adding lastDigit - 1
        if (lastDigit - 1 >= 0) {
            int nextNum = multiplier + (lastDigit - 1);
            if (nextNum > 0 && nextNum <= high) {
                queue.offer(nextNum);
            }
        }

        // Try adding lastDigit + 1
        if (lastDigit + 1 <= 9) {
            int nextNum = multiplier + (lastDigit + 1);
            if (nextNum > 0 && nextNum <= high) {
                queue.offer(nextNum);
            }
        }
    }

    // Sort the result to ensure ascending order
    Collections.sort(result);

    return result;
}

public static int countDigitOne(int n) {
    if (n < 0) return 0;
    int count = 0;
    long multiplier = 1;
    int current = 0, rest = 0;
    while (multiplier <= n) {
        current = (n / multiplier) % 10;
        rest = n % multiplier;
        long higher = n / (multiplier * 10);
        if (current == 0) {
            count += (int) (higher * multiplier);
        } else if (current == 1) {
            count += (int) (higher * multiplier + rest + 1);
        } else {
            count += (int) ((higher + 1) * multiplier);
        }
        multiplier *= 10;
    }
    return count;
}

