    int count = 0;
    boolean[] used = new boolean[n];
    // Precompute which pairs sum to a perfect square
    boolean[][] squareSum = new boolean[n][n];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (i == j) continue;
            squareSum[i][j] = isPerfectSquare(A[i] + A[j]);
        }
    }

    // Start DFS from each element
    for (int start = 0; start < n; start++) {
        used[start] = true;
        dfs(start, 1, n, A, used, squareSum, new java.util.HashMap<Integer, Integer>());
        used[start] = false;
    }

    return count;
}

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }
    int n = heights.length;
    int[] leftSmaller = new int[n];
    int[] rightSmaller = new int[n];
    for (int i = 0; i < n; i++) {
        leftSmaller[i] = -1;
        rightSmaller[i] = n;
    }
    for (int i = 0; i < n; i++) {
        int j = i - 1;
        while (j >= 0 && heights[j] >= heights[i]) {
            j = leftSmaller[j];
        }
        leftSmaller[i] = j;
    }
    for (int i = n - 1; i >= 0; i--) {
        int j = i + 1;
        while (j < n && heights[j] >= heights[i]) {
            j = rightSmaller[j];
        }
        rightSmaller[i] = j;
    }
    int maxArea = 0;
    for (int i = 0; i < n; i++) {
        int width = rightSmaller[i] - leftSmaller[i] - 1;
        int area = heights[i] * width;
        if (area > maxArea) {
            maxArea = area;
        }
    }
    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return new int[0];
    }
    int rows = mat.length;
    int cols = mat[0].length;
    int[] result = new int[rows * cols];
    int dir = 0; // 0: up-right, 1: down-left
    int idx = 0;
    for (int d = 0; d < rows + cols - 1; d++) {
        if (dir == 0) {
            // up-right direction
            int startRow = Math.max(0, d - cols + 1);
            int endRow = Math.min(d, rows - 1);
            for (int r = endRow; r >= startRow; r--) {
                result[idx++] = mat[r][d - r];
            }
        } else {
            // down-left direction
            int startRow = Math.max(0, d - cols + 1);
            int endRow = Math.min(d, rows - 1);
            for (int r = startRow; r <= endRow; r++) {
                result[idx++] = mat[r][d - r];
            }
        }
        dir = 1 - dir;
    }
    return result;
}

public static int findSmallestInteger(int n) {
    if (n <= 0) {
        return -1;
    }

    String s = String.valueOf(n);
    char[] chars = s.toCharArray();
    int len = chars.length;

    // Step 1: Find the rightmost character that is smaller than the next character
    int i = len - 2;
    while (i >= 0 && chars[i] >= chars[i + 1]) {
        i--;
    }

    if (i < 0) {
        // The number is in decreasing order, no larger permutation exists
        return -1;
    }

    // Step 2: Find the smallest character to the right of i that is greater than chars[i]
    int j = len - 1;
    while (j > i && chars[j] <= chars[i]) {
        j--;
    }

    // Step 3: Swap chars[i] and chars[j]
    char temp = chars[i];
    chars[i] = chars[j];
    chars[j] = temp;

    // Step 4: Reverse the suffix starting from i+1 to get the smallest suffix
    int left = i + 1;
    int right = len - 1;
    while (left < right) {
        char t = chars[left];
        chars[left] = chars[right];
        chars[right] = t;
        left++;
        right--;
    }

    String result = new String(chars);

    // Handle cases where the result might have leading zeros (shouldn't happen for positive n, but just in case)
    // Also check if the result is actually greater than n
    try {
        long val = Long.parseLong(result);
        if (val > n) {
            if (val > Integer.MAX_VALUE) {
                return -1;
            }
            return (int) val;
        }
    } catch (NumberFormatException e) {
        return -1;
    }

    return -1;
}

