public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    int current = 1;
    for (int i = 0; i < n; i++) {
        result.add(current);
        // Try to go to the next in lexicographical order
        if (current * 10 <= n) {
            current *= 10;
        } else {
            // Can't go deeper, try to go to the next sibling
            while (current % 10 == 9 || current + 1 > n) {
                current /= 10;
            }
            current++;
        }
    }
    return result;
}

