public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }
    int[] dp = new int[n + 1];
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        dp[i] = i; // worst case: all ones
        for (int j = 1; j * j <= i; j++) {
            int remainder = i - j * j;
            if (dp[remainder] + 1 < dp[i]) {
                dp[i] = dp[remainder] + 1;
            }
        }
    }
    return dp[n];
}

